"""Alembic environment. Used by `radar db init` and by the `alembic` CLI (see alembic.ini)."""

from __future__ import annotations

from typing import Any

from alembic import context

from idea_radar.db import models  # noqa: F401  (registers tables on Base.metadata)
from idea_radar.db.base import Base
from idea_radar.db.session import make_engine
from idea_radar.db.types import UTCDateTime

config = context.config
target_metadata = Base.metadata


def _render_item(type_: str, obj: Any, autogen_context: Any) -> str | bool:
    """Keep autogenerated migrations free of app imports: UTCDateTime -> sa.DateTime(tz)."""
    if type_ == "type" and isinstance(obj, UTCDateTime):
        return "sa.DateTime(timezone=True)"
    return False


def _db_url() -> str:
    url = config.get_main_option("sqlalchemy.url")
    if url:
        return url
    # Invoked via the plain `alembic` CLI: take the URL from Idea Radar's config.
    from idea_radar.config import load_settings

    return load_settings().db_url


def _run(connection: Any) -> None:
    context.configure(
        connection=connection,
        target_metadata=target_metadata,
        render_as_batch=True,  # SQLite needs batch mode for ALTER TABLE
        compare_type=True,
        render_item=_render_item,
    )
    with context.begin_transaction():
        context.run_migrations()


def run_migrations_offline() -> None:
    context.configure(
        url=_db_url(),
        target_metadata=target_metadata,
        literal_binds=True,
        dialect_opts={"paramstyle": "named"},
        render_as_batch=True,
    )
    with context.begin_transaction():
        context.run_migrations()


def run_migrations_online() -> None:
    existing = config.attributes.get("connection")
    if existing is not None:
        _run(existing)
        return
    engine = make_engine(_db_url())
    try:
        with engine.connect() as connection:
            _run(connection)
    finally:
        engine.dispose()


if context.is_offline_mode():
    run_migrations_offline()
else:
    run_migrations_online()
